//! What the test fixtures share (testing/qemu): each fixture is its own module and its own crate, and
//! takes this file as its `fixture` module. Nothing here ships: lemnos.ko has its own (kernel/rs/).
//!
//! - `lb`: the kernel headers the kernel crate's bindings leave out (bindings.h), generated by the
//!   Kbuild with the kernel's bindgen and C flags, so no layout here is written by hand.
//! - `Shared` and `Fixed`: a static the kernel writes, and one it only reads.
//! - `this_module`, `name` and the parameter pieces (`KernelParam`, `modinfo`, `param_int!`): what
//!   THIS_MODULE, a C string in an array, and `module_param` are in C.
#![allow(dead_code)]

use core::cell::UnsafeCell;
use kernel::bindings;
use kernel::ffi::c_char;

/// The fixtures' own bindings: see the module comment.
pub(crate) mod lb {
    #![allow(
        non_camel_case_types,
        non_upper_case_globals,
        non_snake_case,
        dead_code,
        unreachable_pub,
        unsafe_op_in_unsafe_fn,
        improper_ctypes,
        clippy::all,
        clippy::undocumented_unsafe_blocks
    )]

    #[allow(unused_imports)]
    use kernel::{bindings::*, ffi};

    include!(env!("LEMNOS_FIXTURE_BINDINGS"));
}

/// A static the kernel writes through the pointer it is registered with (a descriptor with a list
/// head, a lock or a device in it), or that the fixture writes under a lock of the kernel's.
#[repr(transparent)]
pub(crate) struct Shared<T>(UnsafeCell<T>);

// SAFETY: every use goes through a raw pointer; who may write, and when, is said where each is used.
unsafe impl<T> Sync for Shared<T> {}

impl<T> Shared<T> {
    pub(crate) const fn new(v: T) -> Self {
        Self(UnsafeCell::new(v))
    }

    pub(crate) const fn get(&self) -> *mut T {
        self.0.get()
    }
}

/// A static the kernel only reads: a table of operations, a property, a name.
#[repr(transparent)]
pub(crate) struct Fixed<T>(pub(crate) T);

// SAFETY: never written after it is built; the pointers in it are to statics and functions.
unsafe impl<T> Sync for Fixed<T> {}

impl<T> Fixed<T> {
    pub(crate) const fn get(&self) -> *const T {
        &raw const self.0
    }
}

/// THIS_MODULE. A fixture is always a module: `__this_module` is made by the kernel at load.
pub(crate) const fn this_module() -> *mut bindings::module {
    (&raw const bindings::__this_module).cast_mut()
}

/// A C string in a fixed array, as `.name = "..."` fills one: the bytes, then zeros.
pub(crate) const fn name<const N: usize>(s: &[u8]) -> [c_char; N] {
    let mut out = [0; N];
    let mut i = 0;
    while i < s.len() {
        out[i] = s[i] as c_char;
        i += 1;
    }
    // The terminating NUL has room.
    assert!(s.len() < N);
    out
}

/// A property entry holding one string, as PROPERTY_ENTRY_STRING makes it: the pointer is held inline.
pub(crate) const fn property_string(
    name: &'static core::ffi::CStr,
    value: &'static core::ffi::CStr,
) -> bindings::property_entry {
    bindings::property_entry {
        name: name.as_ptr().cast(),
        length: core::mem::size_of::<*const c_char>(),
        is_inline: true,
        type_: bindings::dev_prop_type_DEV_PROP_STRING,
        __bindgen_anon_1: bindings::property_entry__bindgen_ty_1 {
            value: bindings::property_entry__bindgen_ty_1__bindgen_ty_1 {
                str_: [value.as_ptr().cast()],
            },
        },
    }
}

/// A property entry holding one u32, as PROPERTY_ENTRY_U32 makes it.
pub(crate) const fn property_u32(
    name: &'static core::ffi::CStr,
    value: u32,
) -> bindings::property_entry {
    bindings::property_entry {
        name: name.as_ptr().cast(),
        length: core::mem::size_of::<u32>(),
        is_inline: true,
        type_: bindings::dev_prop_type_DEV_PROP_U32,
        __bindgen_anon_1: bindings::property_entry__bindgen_ty_1 {
            value: bindings::property_entry__bindgen_ty_1__bindgen_ty_1 {
                u32_data: [value, 0],
            },
        },
    }
}

/// The empty entry that ends a property list.
pub(crate) const fn property_end() -> bindings::property_entry {
    // SAFETY: a struct property_entry of zeros is the list's terminator (a NULL name).
    unsafe { core::mem::zeroed() }
}

/// `struct kernel_param`, in the `__param` section the kernel reads a module's parameters from.
#[repr(transparent)]
pub(crate) struct KernelParam(pub(crate) bindings::kernel_param);

// SAFETY: the kernel alone reads it (it is never accessed from Rust), and serialises that itself.
unsafe impl Sync for KernelParam {}

/// A `.modinfo` string as an array, for a static in that section.
pub(crate) const fn modinfo<const N: usize>(s: &[u8]) -> [u8; N] {
    let mut out = [0u8; N];
    let mut i = 0;
    while i < N {
        out[i] = s[i];
        i += 1;
    }
    out
}

/// `param!(name, perm, ops, arg)`: the `struct kernel_param` of `module_param_cb(name, ops, arg, perm)`.
#[allow(unused_macros)]
macro_rules! param {
    ($name:ident, $perm:expr, $ops:expr, $arg:expr) => {
        const _: () = {
            #[link_section = "__param"]
            #[used(compiler)]
            static PARAM: crate::fixture::KernelParam =
                crate::fixture::KernelParam(kernel::bindings::kernel_param {
                    name: concat!(stringify!($name), "\0").as_ptr().cast(),
                    mod_: crate::fixture::this_module(),
                    ops: $ops,
                    perm: $perm,
                    level: -1,
                    flags: 0,
                    __bindgen_anon_1: kernel::bindings::kernel_param__bindgen_ty_1 { arg: $arg },
                });
        };
    };
}
#[allow(unused_imports)]
pub(crate) use param;

/// `param_typed!(name, perm, ops, arg, "type")`: `module_param(name, type, perm)`, with the kernel's own
/// operations for the type and the `parmtype` line modinfo shows.
#[allow(unused_macros)]
macro_rules! param_typed {
    ($name:ident, $perm:expr, $ops:ident, $arg:expr, $tyname:literal) => {
        crate::fixture::param!($name, $perm, &raw const kernel::bindings::$ops, $arg);
        const _: () = {
            const PARMTYPE: &str = concat!("parmtype=", stringify!($name), ":", $tyname, "\0");
            #[link_section = ".modinfo"]
            #[used(compiler)]
            static MI_PARMTYPE: [u8; PARMTYPE.len()] = crate::fixture::modinfo(PARMTYPE.as_bytes());
        };
    };
}
#[allow(unused_imports)]
pub(crate) use param_typed;

/// `parm_desc!(name, "text")`: MODULE_PARM_DESC.
#[allow(unused_macros)]
macro_rules! parm_desc {
    ($name:ident, $desc:literal) => {
        const _: () = {
            const PARM: &str = concat!("parm=", stringify!($name), ":", $desc, "\0");
            #[link_section = ".modinfo"]
            #[used(compiler)]
            static MI_PARM: [u8; PARM.len()] = crate::fixture::modinfo(PARM.as_bytes());
        };
    };
}
#[allow(unused_imports)]
pub(crate) use parm_desc;
